import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Conservative final pass over generated Janino source. It only performs transformations whose legality can be proven
 * from local generated-source structure. Unrecognised source is returned byte-for-byte unchanged.
 */
final class LmdbNativeGeneratedSourceOptimizer {

	private static final String MARKER = "/* rdf4j-fused-sip-factorized */";
	private static final Pattern ARRAY_DOMAIN = Pattern.compile(
			"^(\\s*)long\\[\\]\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*(.+(?:materializeNativeDomain|borrowNativeDomain|nativeDomain).+);\\s*$");
	private static final Pattern CHILD_VALUE = Pattern.compile(
			"^(\\s*)long\\s+([A-Za-z_$][\\w$]*)\\s*=\\s*([A-Za-z_$][\\w$]*)\\.(?:neighborAt|neighborAtInt)\\(([^;]+)\\);\\s*$");
	private static final Pattern FILTER_CONTINUE = Pattern.compile(
			"^(\\s*)if\\s*\\((.+(?:test|accept|compare|filter).+)\\)\\s*\\{?\\s*continue(?:\\s+[A-Za-z_$][\\w$]*)?;\\s*}\\s*$");
	private static final Pattern IDENTIFIER = Pattern.compile("\\b[A-Za-z_$][\\w$]*\\b");

	private LmdbNativeGeneratedSourceOptimizer() {
	}

	static String optimize(String source) {
		if (source == null || source.indexOf(MARKER) >= 0 || source.indexOf("class ") < 0) {
			return source;
		}
		String lineSeparator = source.indexOf("\r\n") >= 0 ? "\r\n" : "\n";
		String[] input = source.split("\\R", -1);
		List<String> lines = new ArrayList<>(input.length + 16);
		lines.add(MARKER);
		Set<String> defined = new HashSet<>();
		for (String line : input) {
			Matcher domain = ARRAY_DOMAIN.matcher(line);
			if (domain.matches()) {
				lines.add(line);
				String variable = domain.group(2);
				String indent = domain.group(1);
				lines.add(indent + "org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbFusedKernelRuntime.installExactDomain("
						+ "org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbFusedKernelRuntime.token(\"" + variable
						+ "\"), " + variable + ", 0, " + variable + ".length);");
				defined.add(variable);
				continue;
			}
			Matcher child = CHILD_VALUE.matcher(line);
			if (child.matches()) {
				String variable = child.group(2);
				lines.add(line);
				lines.add(child.group(1) + "if (!org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbFusedKernelRuntime"
						+ ".sipMayContain(org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbFusedKernelRuntime.token(\""
						+ variable + "\"), " + variable + ")) { continue; }");
				defined.add(variable);
				continue;
			}
			lines.add(line);
			collectDefinitions(line, defined);
		}
		// Filter motion is deliberately limited to straight-line code inside one generated loop body.
		relocateStraightLineFilters(lines);
		return String.join(lineSeparator, lines);
	}

	private static void collectDefinitions(String line, Set<String> defined) {
		Matcher matcher = Pattern.compile("\\b(?:long|int|boolean|double|Object|var)\\s+([A-Za-z_$][\\w$]*)").matcher(line);
		while (matcher.find()) {
			defined.add(matcher.group(1));
		}
	}

	private static void relocateStraightLineFilters(List<String> lines) {
		for (int at = 0; at < lines.size(); at++) {
			Matcher filter = FILTER_CONTINUE.matcher(lines.get(at));
			if (!filter.matches()) {
				continue;
			}
			String expression = filter.group(2);
			if (expression.contains("optional") || expression.contains("minus") || expression.contains("leftJoin")
					|| expression.contains("random") || expression.contains("now(")) {
				continue;
			}
			Set<String> required = identifiers(expression);
			int earliest = at;
			int depth = depthBefore(lines, at);
			for (int candidate = at - 1; candidate >= 0; candidate--) {
				String line = lines.get(candidate);
				if (depthBefore(lines, candidate) != depth || isSemanticBarrier(line)) {
					break;
				}
				if (definesAny(line, required)) {
					earliest = candidate + 1;
					break;
				}
				earliest = candidate;
			}
			if (earliest < at) {
				String moved = lines.remove(at);
				lines.add(earliest, moved);
			}
		}
	}

	private static boolean isSemanticBarrier(String line) {
		return line.contains("OPTIONAL") || line.contains("MINUS") || line.contains("LeftJoin")
				|| line.contains("try {") || line.contains("catch (") || line.contains("finally")
				|| line.contains("emit") || line.contains("addResult") || line.contains("return ");
	}

	private static Set<String> identifiers(String expression) {
		Set<String> result = new HashSet<>();
		Matcher matcher = IDENTIFIER.matcher(expression);
		while (matcher.find()) {
			String value = matcher.group();
			if (!isKeyword(value)) {
				result.add(value);
			}
		}
		return result;
	}

	private static boolean isKeyword(String value) {
		return switch (value) {
		case "if", "true", "false", "null", "long", "int", "boolean", "double", "continue", "this" -> true;
		default -> Character.isUpperCase(value.charAt(0));
		};
	}

	private static boolean definesAny(String line, Set<String> required) {
		for (String value : required) {
			if (line.matches(".*\\b(?:long|int|boolean|double|Object|var)\\s+" + Pattern.quote(value) + "\\b.*")) {
				return true;
			}
		}
		return false;
	}

	private static int depthBefore(List<String> lines, int end) {
		int depth = 0;
		for (int i = 0; i < end; i++) {
			String line = lines.get(i);
			for (int c = 0; c < line.length(); c++) {
				char ch = line.charAt(c);
				if (ch == '{') {
					depth++;
				} else if (ch == '}') {
					depth--;
				}
			}
		}
		return depth;
	}
}
